const body = $input.first().json;
const payload = body.payload ?? body;
const attendees = payload.attendees ?? payload.responses?.attendees ?? [];
const firstAttendee = Array.isArray(attendees) ? attendees[0] ?? {} : {};
const email =
  firstAttendee.email ??
  payload.email ??
  payload.responses?.email?.value ??
  '';
const attendeeName = firstAttendee.name ?? payload.name ?? email;
const title = payload.title ?? payload.eventTitle ?? 'Cal.com booking';
const startTime = payload.startTime ?? payload.start ?? '';

if (!email) {
  throw new Error('Cal.com payload has no attendee email');
}

return [
  {
    json: {
      email,
      attendeeName,
      title,
      startTime,
      findPersonBody: {
        query:
          'query PersonByEmail($email: String!) { people(filter: { emails: { primaryEmail: { eq: $email } } }, first: 1) { edges { node { id companyId name { firstName lastName } } } } }',
        variables: { email },
      },
    },
  },
];

const booking = $('Normalize booking').first().json;
const gql = $input.first().json;
const person = gql.data?.people?.edges?.[0]?.node ?? null;

if (!person?.id) {
  throw new Error(`No Twenty person for ${booking.email}`);
}

const markdown = [
  `Cal.com: ${booking.title}`,
  booking.startTime ? `When: ${booking.startTime}` : '',
  `Attendee: ${booking.attendeeName} <${booking.email}>`,
]
  .filter(Boolean)
  .join('\n');

return [
  {
    json: {
      personId: person.id,
      companyId: person.companyId ?? null,
      createNoteBody: {
        title: booking.title,
        bodyV2: { markdown },
      },
    },
  },
];

const built = $('Build note').first().json;
const created = $input.first().json;
const noteId = created.data?.id ?? created.id;

if (!noteId) {
  throw new Error('createNote did not return an id');
}

const target = { noteId, personId: built.personId };
if (built.companyId) {
  target.companyId = built.companyId;
}

return [{ json: { noteId, target } }];
